const {
  reservationDate,
  reservationTime,
  partySize,
  guestName,
  phoneNumber,
  occasion,
  seatingNeeds,
  allergyNotes,
} = args;

const isValidIsoDate = (value) => {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
};

const isValidTime = (value) => {
  const match = typeof value === "string" && value.match(/^(\d{2}):(\d{2})$/);
  return Boolean(match) && Number(match[1]) < 24 && Number(match[2]) < 60;
};

const requiredTextIsValid = [guestName, phoneNumber].every(
  (value) => typeof value === "string" && value.trim().length > 0,
);
const notesAreValid = [occasion, seatingNeeds, allergyNotes].every(
  (value) => typeof value === "string",
);

if (!isValidIsoDate(reservationDate) || !isValidTime(reservationTime) || !Number.isInteger(partySize) || !requiredTextIsValid || !notesAreValid) {
  return {
    status: "failed",
    reason: "missing_or_invalid_required_information",
  };
}

if (partySize < 1 || partySize > 8) {
  return {
    status: "failed",
    reason: "party_size_not_supported",
  };
}

if (reservationTime !== "18:45" && reservationTime !== "20:00") {
  return {
    status: "failed",
    reason: "slot_not_available",
  };
}

return {
  status: "confirmed",
  confirmationCode: "EV-2048",
  reservationDate,
  reservationTime,
  partySize,
};
